begin;
set local signalword.local_fixture='true';
select no_plan();
insert into auth.users(id) values('d1000000-0000-4000-8000-000000000001');
insert into public.profiles(id,display_name) values('d1000000-0000-4000-8000-000000000001','Delivery fixture');
select ok(not has_table_privilege('authenticated','public.contact_join_delivery_evidence','SELECT'),'recipient delivery evidence is private');
select ok(not has_function_privilege('service_role','public.reconcile_resend_before_joins(text,text,text,text)','EXECUTE'),'old callback cannot bypass join reconciliation');
set local role service_role;
select set_config('request.jwt.claim.role','service_role',true);
select public.create_contact_invitation('d1000000-0000-4000-8000-000000000001','d2000000-0000-4000-8000-000000000001',extensions.digest('delivery-invite','sha256'),repeat('x',48),1)->>'invitationId' as invite \gset
select public.begin_contact_join(extensions.digest('delivery-invite','sha256'),'d3000000-0000-4000-8000-000000000001',repeat('cipher',10),extensions.digest('first-email','sha256'),1,extensions.digest('code','sha256'),repeat('payload',10),1,'2026-10-19',true,'resend');
reset role;
select is((select state from public.contact_join_delivery_evidence),'queued','queue insertion records non-PII delivery evidence');
set local role service_role;
select public.claim_contact_join_email('d4000000-0000-4000-8000-000000000001');
select public.reconcile_resend_webhook('join-event-1','join-message-1','delivered',encode(extensions.digest('contact/join/d3000000-0000-4000-8000-000000000001','sha256'),'hex'));
select is(public.finish_contact_join_email('d3000000-0000-4000-8000-000000000001','d4000000-0000-4000-8000-000000000001','sent','join-message-1'),false,'callback before finish clears lease without a duplicate send');
select is(public.reconcile_resend_webhook('join-event-1','join-message-1','delivered',encode(extensions.digest('contact/join/d3000000-0000-4000-8000-000000000001','sha256'),'hex')),false,'duplicate signed receipt is idempotent');
select public.reconcile_resend_webhook('join-event-2','join-message-1','bounced');
select public.reconcile_resend_webhook('join-event-3','join-message-1','delivered');
reset role;
select is((select state from public.contact_join_delivery_evidence),'bounced','failure takes precedence over later delivery receipt');
select is((select delivery_state from public.contact_join_attempts),'failed','callback failure updates live queue too');
set local role authenticated;
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claim.sub','d1000000-0000-4000-8000-000000000001',true);
select public.revoke_contact_invitation('d1000000-0000-4000-8000-000000000001',:'invite'::uuid);
reset role;
select public.purge_expired_contact_joins();
select is((select count(*) from public.contact_join_attempts),0::bigint,'recipient data is purged');
select is((select state from public.contact_join_delivery_evidence),'bounced','delivery evidence survives recipient data purge');
set local role service_role;
select set_config('request.jwt.claim.role','service_role',true);
select public.create_contact_invitation('d1000000-0000-4000-8000-000000000001','d2000000-0000-4000-8000-000000000002',extensions.digest('unknown-invite','sha256'),repeat('x',48),1);
select throws_ok($$select public.begin_contact_join(extensions.digest('unknown-invite','sha256'),'d3000000-0000-4000-8000-000000000001',repeat('cipher',10),extensions.digest('retired-email','sha256'),1,extensions.digest('code','sha256'),repeat('payload',10),1,'2026-10-19',true,'resend')$$,'22023','JOIN_REQUEST_RETIRED','purged attempt ID cannot reuse a provider idempotency key');
select public.begin_contact_join(extensions.digest('unknown-invite','sha256'),'d3000000-0000-4000-8000-000000000002',repeat('cipher',10),extensions.digest('second-email','sha256'),1,extensions.digest('code2','sha256'),repeat('payload',10),1,'2026-10-19',true,'resend');
select public.claim_contact_join_email('d4000000-0000-4000-8000-000000000002');
reset role;
select public.reconcile_restore_journal('d5000000-0000-4000-8000-000000000001',1,repeat('a',64),'[]');
select is((select state from public.contact_join_delivery_evidence where attempt_id='d3000000-0000-4000-8000-000000000002'),'unknown','restore preserves uncertain send evidence while invalidating code');
select is((public.signalword_operational_health()->'joinVerification'->>'unknown')::integer,1,'health exposes uncertainty count without recipient data');
set local role service_role;
select public.reconcile_resend_webhook('join-event-4','join-message-2','delivered',encode(extensions.digest('contact/join/d3000000-0000-4000-8000-000000000002','sha256'),'hex'));
select is(public.claim_contact_join_email('d4000000-0000-4000-8000-000000000003'),null::jsonb,'late receipt cannot requeue purged email');
reset role;
select is((select state from public.contact_join_delivery_evidence where attempt_id='d3000000-0000-4000-8000-000000000002'),'delivered','late callback reconciles even after restore and purge');
select is((public.signalword_operational_health()->'joinVerification'->>'unknown')::integer,0,'receipt settles unknown health count');
insert into auth.users(id) values('d1000000-0000-4000-8000-000000000002');
insert into public.profiles(id,display_name) values('d1000000-0000-4000-8000-000000000002','Deleting sender');
set local role service_role;
select public.create_contact_invitation('d1000000-0000-4000-8000-000000000002','d2000000-0000-4000-8000-000000000003',extensions.digest('blocked-invite','sha256'),repeat('x',48),1);
select public.create_contact_invitation('d1000000-0000-4000-8000-000000000001','d2000000-0000-4000-8000-000000000004',extensions.digest('live-invite','sha256'),repeat('x',48),1);
select public.begin_contact_join(extensions.digest('blocked-invite','sha256'),'d3000000-0000-4000-8000-000000000003',repeat('cipher',10),extensions.digest('blocked-email','sha256'),1,extensions.digest('code','sha256'),repeat('payload',10),1,'2026-10-19',true,'fake');
select public.begin_contact_join(extensions.digest('live-invite','sha256'),'d3000000-0000-4000-8000-000000000004',repeat('cipher',10),extensions.digest('live-email','sha256'),1,extensions.digest('code','sha256'),repeat('payload',10),1,'2026-10-19',true,'fake');
reset role;
insert into public.pending_deletions(user_id,receipt_hash) values('d1000000-0000-4000-8000-000000000002',extensions.digest('pending','sha256'));
set local role service_role;
select is(public.claim_contact_join_email('d4000000-0000-4000-8000-000000000004')->>'attemptId','d3000000-0000-4000-8000-000000000004','pending deletion cannot starve another recipient queue');
select public.begin_contact_join(extensions.digest('live-invite','sha256'),'d3000000-0000-4000-8000-000000000005',repeat('cipher',10),extensions.digest('live-email-2','sha256'),1,extensions.digest('code','sha256'),repeat('payload',10),1,'2026-10-19',true,'fake');
reset role;
update public.contact_join_attempts set lease_expires_at=now()-interval '1 second' where id='d3000000-0000-4000-8000-000000000004';
set local role service_role;
select is(public.claim_contact_join_email('d4000000-0000-4000-8000-000000000005')->>'attemptId','d3000000-0000-4000-8000-000000000005','expired lease recovery continues to the next eligible message');
reset role;
update public.contact_join_delivery_evidence set created_at=now()-interval '8 days' where attempt_id is not null;
select public.purge_expired_contact_joins();
select is((select count(*) from public.contact_join_delivery_evidence),0::bigint,'minimal audit evidence has bounded retention');
select * from finish();
rollback;
